using System.Collections.Generic;
using UnityEngine;
// Embedded only in AV1 build scene copies; absent from basic builds and authored scenes.
[DefaultExecutionOrder(500)]public sealed class PresentationBootstrap:MonoBehaviour
{
 public PresentationProfile profile;public static PresentationBootstrap Instance{get;private set;}
 public readonly Dictionary<string,int> Plays=new(),Effects=new();readonly Dictionary<string,double> lastSound=new();AudioSource source;AudioListener listener;double scanAt;
 PlayerInputReader player;PlayerHealth health;PlayerDash dash;PlayerMotor motor;PlayerAttack attack;bool oldDash,ownedDash,ownedDouble,dead;int oldDouble;uint oldAttack,jumpSequence;float previousVy;BossEncounter boss;double bossPhase=-1;
 void Awake(){if(Instance!=null){Destroy(gameObject);return;}Instance=this;DontDestroyOnLoad(gameObject);source=gameObject.AddComponent<AudioSource>();source.playOnAwake=false;source.spatialBlend=0;listener=gameObject.AddComponent<AudioListener>();listener.enabled=false;HitFeedback.Presented+=Hit;Debug.Log("AV1 enabled "+profile.name);}
 void OnDestroy(){if(Instance!=this)return;HitFeedback.Presented-=Hit;if(health!=null){health.Hit-=Hurt;health.Restored-=Restored;}Instance=null;}
 public bool Play(string id){if(GameState.GetOrCreate().Paused)return false;if(lastSound.TryGetValue(id,out var at)&&Time.timeAsDouble-at<profile.soundThrottle)return false;var s=System.Array.Find(profile.sounds,x=>x.eventName==id);if(s==null||s.clip==null)return false;lastSound[id]=Time.timeAsDouble;source.pitch=1+Random.Range(-s.pitchVariation,s.pitchVariation);source.PlayOneShot(s.clip,s.volume);Plays.TryGetValue(id,out int n);Plays[id]=n+1;Debug.Log("AV1 AUDIO "+id+" clip="+s.clip.name);return true;}
 public void Effect(string id){Effects.TryGetValue(id,out int n);Effects[id]=n+1;if(n==0)Debug.Log("AV1 EFFECT "+id);}
 void Hurt(){if(health.HP<=0){if(!dead){dead=true;Play("death");Effect("death");}}else{Play("hurt");Effect("hurt");}}
 void Restored(){dead=false;if(RoomSession.Instance!=null&&!RoomSession.Instance.Respawning&&!RoomSession.Instance.Transitioning&&RoomSession.Instance.CheckpointId!=null)Play("checkpoint");}
 void Hit(HitFeedback feedback,int hp){Play("hit");if(feedback.GetComponent<BossEncounter>()!=null&&hp==0)Play("victory");if(hp==0&&feedback.GetComponent<BossEncounter>()==null){Effect("fragments");PresentationVisual.Fragments(feedback,profile);}}
 void Bind(){bool other=false;foreach(var l in FindObjectsByType<AudioListener>(FindObjectsSortMode.None))if(l!=listener&&l.enabled)other=true;listener.enabled=!other;var p=RoomSession.Instance?.Player;if(p!=player){if(health!=null){health.Hit-=Hurt;health.Restored-=Restored;}player=p;if(p!=null){health=p.GetComponent<PlayerHealth>();dash=p.GetComponent<PlayerDash>();motor=p.GetComponent<PlayerMotor>();attack=p.GetComponent<PlayerAttack>();health.Hit+=Hurt;health.Restored+=Restored;ownedDash=dash.hasDash;ownedDouble=motor.hasDoubleJump;oldAttack=attack.Sequence;oldDouble=motor.DoubleJumpsPerformed;jumpSequence=p.JumpSequence;previousVy=0;}}
 foreach(var sr in FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None)){int k=sr.GetComponent<PlayerMotor>()!=null?0:sr.GetComponent<EnemyPatrol>()!=null?1:sr.GetComponent<EnemyCharger>()!=null?2:sr.GetComponent<EnemyTurret>()!=null?3:sr.GetComponent<BossEncounter>()!=null?4:-1;if(k>=0&&sr.GetComponent<PresentationVisual>()==null)sr.gameObject.AddComponent<PresentationVisual>().Initialize(profile,k);}boss=FindFirstObjectByType<BossEncounter>();}
 void Update(){if(Time.unscaledTimeAsDouble>=scanAt){scanAt=Time.unscaledTimeAsDouble+.1;Bind();}if(GameState.GetOrCreate().Paused)return;if(player!=null){if(dash.IsDashing&&!oldDash){Play("dash");Effect("dash");}oldDash=dash.IsDashing;if(attack.Sequence!=oldAttack){oldAttack=attack.Sequence;Play("swing");Effect("attack");}if((dash.hasDash&&!ownedDash)||(motor.hasDoubleJump&&!ownedDouble))Play("ability");ownedDash=dash.hasDash;ownedDouble=motor.hasDoubleJump;}if(boss!=null&&boss.PhaseStarted!=bossPhase){bossPhase=boss.PhaseStarted;if(boss.State.ToString().EndsWith("Tell"))Play("bossTell");}}
 void FixedUpdate(){if(player==null||player.InputLocked)return;float vy=player.GetComponent<Rigidbody2D>().linearVelocity.y;if((player.JumpSequence!=jumpSequence&&vy>1&&vy>previousVy+2)||motor.DoubleJumpsPerformed!=oldDouble){Play("jump");Effect("jump");}jumpSequence=player.JumpSequence;oldDouble=motor.DoubleJumpsPerformed;previousVy=vy;}
}
